// Same-page QNN playground, isolated from the game's DOM and seeded RNG.
const host = document.getElementById('qnn-playground-mount');
if (host) {
  const root = host.attachShadow({mode:'open'});
  root.innerHTML = '<link rel="stylesheet" href="assets/qnn-playground/playground.css"><div class="qnn-surface guided">' + "\n\n  <!-- Top Controls -->\n  <div id=\"top-controls\">\n    <div class=\"container l--page\">\n      <div class=\"timeline-controls\">\n        <button class=\"mdl-button mdl-js-button mdl-button--icon ui-resetButton\" id=\"reset-button\" title=\"Reset the network\">\n          <i class=\"material-icons\" aria-hidden=\"true\">↺</i>\n        </button>\n        <button class=\"mdl-button mdl-js-button mdl-button--fab mdl-button--colored ui-playButton\" id=\"play-pause-button\" title=\"Run/Pause\">\n          <i class=\"material-icons\" aria-hidden=\"true\">▶</i>\n          <i class=\"material-icons\" aria-hidden=\"true\">Ⅱ</i>\n        </button>\n        <button class=\"mdl-button mdl-js-button mdl-button--icon ui-stepButton\" id=\"next-step-button\" title=\"Step\">\n          <i class=\"material-icons\" aria-hidden=\"true\">▸|</i>\n        </button>\n      </div>\n      <div class=\"control\">\n        <span class=\"label\">Epoch</span>\n        <span class=\"value\" id=\"iter-number\"></span>\n      </div>\n      <div class=\"control ui-learningRate\">\n        <label for=\"learningRate\">Learning rate</label>\n        <div class=\"select\">\n          <select id=\"learningRate\">\n            <option value=\"0.00001\">0.00001</option>\n            <option value=\"0.0001\">0.0001</option>\n            <option value=\"0.001\">0.001</option>\n            <option value=\"0.003\">0.003</option>\n            <option value=\"0.01\">0.01</option>\n            <option value=\"0.03\">0.03</option>\n            <option value=\"0.1\">0.1</option>\n            <option value=\"0.3\">0.3</option>\n            <option value=\"1\">1</option>\n            <option value=\"3\">3</option>\n            <option value=\"10\">10</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"control ui-entangler\">\n        <label for=\"entanglers\">Entangler</label>\n        <div class=\"select\">\n          <select id=\"entanglers\">\n            <option value=\"cnot\">CNOT ring</option>\n            <option value=\"cry\">CRY ring (trainable)</option>\n            <option value=\"none\">None</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"control ui-shots\">\n        <label for=\"shots\">Measurement shots</label>\n        <div class=\"select\">\n          <select id=\"shots\">\n            <option value=\"0\">&infin; (exact)</option>\n            <option value=\"1000\">1000</option>\n            <option value=\"100\">100</option>\n            <option value=\"10\">10</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"control ui-reupload\">\n        <label for=\"reupload\">Data re-uploading</label>\n        <div class=\"select\">\n          <select id=\"reupload\">\n            <option value=\"true\">Every layer</option>\n            <option value=\"false\">First layer only</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"control ui-readout\">\n        <label for=\"readouts\">Readout</label>\n        <div class=\"select\">\n          <select id=\"readouts\">\n            <option value=\"project\">Hybrid: Z-strings &rarr; sigmoid</option>\n            <option value=\"z0\">Quantum only: &lang;Z&#8320;&rang;</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"control ui-mode\">\n        <button class=\"mode-toggle\" id=\"mode-toggle\"></button>\n      </div>\n    </div>\n  </div>\n\n  <!-- Guided steps (simple view) -->\n  <div id=\"guide\" class=\"l--page\"></div>\n\n  <!-- Main Part -->\n  <div id=\"main-part\" class=\"l--page\">\n\n    <!--  Data Column-->\n    <div class=\"column data\">\n      <h4>\n        <span>Data</span>\n      </h4>\n      <div class=\"ui-dataset\">\n        <p>Pick a world</p>\n        <div class=\"world-list\" id=\"world-list\"></div>\n        <p class=\"scene-name\"></p>\n        <button class=\"basic-button\" id=\"load-weights\" title=\"Use the exact weights the demo site uses\">\n          Load demo weights\n        </button>\n        <p class=\"patch-caption\">Training examples <span class=\"patch-key\"><b class=\"pos\">&#10003;</b> target &nbsp;<b class=\"neg\">&#10007;</b> not</span></p>\n        <div id=\"patch-strip\"></div>\n      </div>\n      <div>\n        <div class=\"ui-percTrainData\">\n          <label for=\"percTrainData\">Ratio of training to test data:&nbsp;&nbsp;<span class=\"value\">XX</span>%</label>\n          <p class=\"slider\">\n            <input class=\"mdl-slider mdl-js-slider\" type=\"range\" id=\"percTrainData\" min=\"10\" max=\"90\" step=\"10\">\n          </p>\n        </div>\n        <div class=\"ui-noise\">\n          <label for=\"noise\">Noise:&nbsp;&nbsp;<span class=\"value\">XX</span></label>\n          <p class=\"slider\">\n            <input class=\"mdl-slider mdl-js-slider\" type=\"range\" id=\"noise\" min=\"0\" max=\"50\" step=\"5\">\n          </p>\n        </div>\n        <div class=\"ui-batchSize\">\n          <label for=\"batchSize\">Batch size:&nbsp;&nbsp;<span class=\"value\">XX</span></label>\n          <p class=\"slider\">\n            <input class=\"mdl-slider mdl-js-slider\" type=\"range\" id=\"batchSize\" min=\"1\" max=\"30\" step=\"1\">\n          </p>\n        </div>\n          <button class=\"basic-button\" id=\"data-regen-button\" title=\"Regenerate data\">\n            Regenerate\n          </button>\n      </div>\n    </div>\n\n    <!-- Features Column -->\n    <div class=\"column features\">\n      <h4>Features</h4>\n      <p>Which pixel features do you feed in?</p>\n      <div id=\"network-scroll\"><div id=\"network\">\n        <svg id=\"svg\" width=\"510\" height=\"450\">\n          <defs>\n            <marker id=\"markerArrow\" markerWidth=\"7\" markerHeight=\"13\" refX=\"1\" refY=\"6\" orient=\"auto\" markerUnits=\"userSpaceOnUse\">\n              <path d=\"M2,11 L7,6 L2,2\" />\n            </marker>\n          </defs>\n        </svg>\n        <!-- Hover card -->\n        <div id=\"hovercard\">\n          <div class=\"hint\"></div>\n          <div class=\"gate\"></div>\n        </div>\n        <div class=\"callout thumbnail\">\n          <svg viewBox=\"0 0 30 30\">\n            <defs>\n              <marker id=\"arrow\" markerWidth=\"5\" markerHeight=\"5\" refx=\"5\" refy=\"2.5\" orient=\"auto\" markerUnits=\"userSpaceOnUse\">\n                <path d=\"M0,0 L5,2.5 L0,5 z\"/>\n              </marker>\n            </defs>\n            <path d=\"M12,30C5,20 2,15 12,0\" marker-end=\"url(#arrow)\">\n          </svg>\n          <div class=\"label\">\n            This box is &lang;Z&rang; of one <b>qubit</b> for every region of the scene; the sphere below is its state for the probe region. Hover to enlarge; click to edit.\n          </div>\n        </div>\n        <div class=\"callout weights\">\n          <svg viewBox=\"0 0 30 30\">\n            <defs>\n              <marker id=\"arrow\" markerWidth=\"5\" markerHeight=\"5\" refx=\"5\" refy=\"2.5\" orient=\"auto\" markerUnits=\"userSpaceOnUse\">\n                <path d=\"M0,0 L5,2.5 L0,5 z\"/>\n              </marker>\n            </defs>\n            <path d=\"M12,30C5,20 2,15 12,0\" marker-end=\"url(#arrow)\">\n          </svg>\n          <div class=\"label\">\n            Each feature sets a fixed <b>rotation angle</b>, &pi; &times; its value, on one qubit.\n          </div>\n        </div>\n      </div></div>\n    </div>\n\n    <!-- Hidden Layers Column -->\n    <div class=\"column hidden-layers\">\n      <h4>\n        <div class=\"ui-numHiddenLayers\">\n          <button id=\"add-layers\" class=\"mdl-button mdl-js-button mdl-button--icon\">\n            <i class=\"material-icons\" aria-hidden=\"true\">+</i>\n          </button>\n          <button id=\"remove-layers\" class=\"mdl-button mdl-js-button mdl-button--icon\">\n            <i class=\"material-icons\" aria-hidden=\"true\">−</i>\n          </button>\n        </div>\n        <span id=\"num-layers\"></span>\n        <span id=\"layers-label\"></span>\n      </h4>\n      <div class=\"bracket\"></div>\n    </div>\n\n    <!-- Output Column -->\n    <div class=\"column output\">\n      <h4>Output</h4>\n      <div class=\"metrics\">\n        <div class=\"output-stats loss ui-percTrainData\">\n          <span>Test loss</span>\n          <div class=\"value\" id=\"loss-test\"></div>\n        </div>\n        <div class=\"output-stats loss train\">\n          <span>Training loss</span>\n          <div class=\"value\" id=\"loss-train\"></div>\n        </div>\n        <div class=\"output-stats train\">\n          <span id=\"accuracy-label\" title=\"Illustrative generated-window check; pair information may overlap across splits\">Illustrative window check</span>\n          <div class=\"value\" id=\"accuracy\"></div>\n        </div>\n        <div class=\"output-stats train baseline-row\" title=\"Logistic regression on the same 8 features and windows (the site's matched classical baseline)\">\n          <span>Classical baseline</span>\n          <div class=\"value\" id=\"baseline\"></div>\n        </div>\n        <div id=\"linechart\"></div>\n      </div>\n      <div id=\"scene-view\">\n        <canvas id=\"scene-canvas\" width=\"512\" height=\"512\" tabindex=\"0\"\n            aria-label=\"Scene. Each region is scored by the quantum classifier. Click a region, or use the arrow keys, to inspect its quantum state.\"></canvas>\n      </div>\n      <div id=\"square-info\" aria-live=\"polite\"></div>\n      <div id=\"scene-legend\"></div>\n      <div id=\"compare-panel\">\n        <b>Does the quantum part matter?</b> Train circuits with and without entanglement on the same windows and compare them with a classical baseline.\n        <button class=\"basic-button small\" id=\"compare-run\">Compare (about 5 s)</button>\n        <div id=\"compare-result\"></div>\n      </div>\n      <div id=\"search-banner\" aria-live=\"polite\"></div>\n      <div class=\"scene-controls\">\n        <label for=\"threshold\">Threshold <span class=\"value\"></span></label>\n        <input type=\"range\" id=\"threshold\" min=\"0.05\" max=\"0.99\" step=\"any\">\n        <select id=\"grid-size\" title=\"Grover address grid (regions per side)\"></select>\n        <select id=\"target-height\" title=\"Wanda's height in pixels: supplied to the classifier, as on the site\"></select>\n        <button class=\"basic-button small\" id=\"move-target\">Move target</button>\n        <button class=\"basic-button small\" id=\"random-spot\" title=\"Put the target anywhere, possibly across a border\">Random spot</button>\n        <button class=\"basic-button small\" id=\"toggle-target\">Remove target</button>\n      </div>\n      <div style=\"float:left;margin-top:20px\">\n        <div style=\"display:flex; align-items:center;\">\n\n          <!-- Gradient color scale -->\n          <div class=\"label\" id=\"colormap-label\" style=\"width:105px; margin-right: 10px\">\n            Colors: &lang;Z&rang; &minus;1&hellip;1; scores and features 0&hellip;1 (blue = high); angles &minus;&pi;&hellip;&pi;.\n          </div>\n          <svg width=\"150\" height=\"30\" id=\"colormap\">\n            <defs>\n              <linearGradient id=\"gradient\" x1=\"0%\" y1=\"100%\" x2=\"100%\" y2=\"100%\">\n                <stop offset=\"0%\" stop-color=\"#f59322\" stop-opacity=\"1\"></stop>\n                <stop offset=\"50%\" stop-color=\"#e8eaeb\" stop-opacity=\"1\"></stop>\n                <stop offset=\"100%\" stop-color=\"#0877bd\" stop-opacity=\"1\"></stop>\n              </linearGradient>\n            </defs>\n            <g class=\"core\" transform=\"translate(3, 0)\">\n              <rect width=\"144\" height=\"10\" style=\"fill: url('#gradient');\"></rect>\n            </g>\n          </svg>\n        </div>\n        <br/>\n        <div style=\"display:flex;\">\n          <label class=\"ui-discretize mdl-checkbox mdl-js-checkbox mdl-js-ripple-effect\" for=\"discretize\">\n            <input type=\"checkbox\" id=\"discretize\" class=\"mdl-checkbox__input\" checked>\n            <span class=\"mdl-checkbox__label label\">Show only marked squares</span>\n          </label>\n        </div>\n      </div>\n    </div>\n\n  </div>\n\n  <!-- Search, readout, state and comparison: one row of cards -->\n  <section id=\"panels\" class=\"panels l--page\"></section>\n\n  <!-- About: one compact strip instead of the template's long article -->\n  <section id=\"article-text\" class=\"about l--page\">\n    <div class=\"about-card\">\n      <h3>How it works</h3>\n      <p>8 pixel features of a Wanda-sized window become fixed RY/RZ angles on 4 qubits (the site’s register; the details view allows up to 6), followed by learned rotations and a CNOT ring, in every layer. The measured averages give a score. 4096 windows are scored and each square keeps its best, as on the site. Squares above the threshold, after the site's suppression of nearby duplicates, become the oracle of Grover's search. The artwork, features, circuit, scan and (with <b>Load demo weights</b>) the trained weights and threshold are the Where's Wanda site's own; scores match it to ~10<sup>&minus;15</sup>.</p>\n    </div>\n    <div class=\"about-card\">\n      <h3>Reading the picture</h3>\n      <ul>\n        <li><b>Boxes</b>: one qubit's value for every square (blue +1 / orange &minus;1).</li>\n        <li><b>Scene</b>: blue = score, dashed = marked, frame = the square you're inspecting.</li>\n        <li><b>Spheres, arcs</b> (details view): the qubits for that square; solid arc = entangled pair.</li>\n        <li><b>Faded</b> gates can't affect the result.</li>\n      </ul>\n    </div>\n    <div class=\"about-card\">\n      <h3>Honest scorecard</h3>\n      <ul>\n        <li>All squares are scored first, so the default search shows how Grover behaves, not a speed-up. The <b>coherent oracle</b> (details view) runs the classifier inside the search.</li>\n        <li>A classical baseline matches the circuit on these tasks; <b>Compare</b> shows it.</li>\n        <li>Live scores check generated windows from these same worlds. Training pairs can overlap across the split, so this is illustrative, not the frozen model’s reserved benchmark. Everything is simulated.</li>\n      </ul>\n    </div>\n    <div class=\"about-card\">\n      <h3>Credits</h3>\n      <p>A fork of the <a href=\"https://github.com/tensorflow/playground\">TensorFlow Playground</a> by Daniel Smilkov and Shan Carter (Apache&nbsp;2.0), with a quantum engine and image-search pipeline by the quantum-image-search team. Background: Schuld &amp; Petruccione, <a href=\"https://link.springer.com/book/10.1007/978-3-030-83098-4\"><i>Machine Learning with Quantum Computers</i></a>; P&eacute;rez-Salinas et al., <a href=\"https://quantum-journal.org/papers/q-2020-02-06-226/\">data re-uploading</a>.</p>\n      <details class=\"lesson\">\n        <summary>Tailor the controls for a lesson</summary>\n        <p>Untick controls to hide them, then save <a class=\"hide-controls-link\" href=\"#\">this link</a>.</p>\n        <div class=\"hide-controls\"></div>\n      </details>\n    </div>\n  </section>\n\n  <!-- Footer -->\n  \n\n" + '</div>';
  const styles = root.querySelector('link');
  const styled = new Promise((resolve,reject) => { styles.addEventListener('load',resolve,{once:true}); styles.addEventListener('error',reject,{once:true}); });
  let started = false;
  const start = async () => {
    if (started) return;
    started = true;
    host.setAttribute('data-playground-state','loading');
    host.setAttribute('aria-busy','true');
    try { await styled; await import('./assets/qnn-playground/engine.js'); }
    catch(error) { host.setAttribute('data-playground-state','error'); host.insertAdjacentHTML('beforebegin','<p role="alert" class="playground-error">The playground could not load. Refresh to try again.</p>'); console.error(error); }
  };
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(entries => { if(entries.some(entry=>entry.isIntersecting)) { observer.disconnect(); start(); } }, {rootMargin:'160px'});
    observer.observe(host);
  } else { start(); }
}
